from datetime import datetime
from dataclasses import dataclass
from typing import List, Dict, Any, Optional

class CounselingBookingEngine:
    def __init__(self, db_path: str = ":memory:"):
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row
        self._init_db()

    def _init_db(self):
        with self.conn:
            self.conn.executescript("""
                CREATE TABLE IF NOT EXISTS counselors (
                    counselor_id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    specialty TEXT
                );
                CREATE TABLE IF NOT EXISTS slots (
                    slot_id TEXT PRIMARY KEY,
                    counselor_id TEXT,
                    start_time TEXT,
                    status TEXT,
                    FOREIGN KEY(counselor_id) REFERENCES counselors(counselor_id)
                );
                CREATE TABLE IF NOT EXISTS session_passes (
                    client_email TEXT PRIMARY KEY,
                    remaining_sessions INTEGER DEFAULT 0,
                    used_sessions INTEGER DEFAULT 0
                );
                CREATE TABLE IF NOT EXISTS pass_ledger (
                    entry_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    client_email TEXT,
                    booking_id TEXT,
                    entry_type TEXT,
                    delta_sessions INTEGER,
                    idempotency_key TEXT UNIQUE
                );
                CREATE TABLE IF NOT EXISTS bookings (
                    booking_id TEXT PRIMARY KEY,
                    counselor_id TEXT,
                    start_time TEXT,
                    client_name TEXT,
                    client_email TEXT,
                    status TEXT,
                    idempotency_key TEXT,
                    FOREIGN KEY(counselor_id, start_time) REFERENCES slots(counselor_id, start_time)
                );
                CREATE TABLE IF NOT EXISTS waitlist (
                    waitlist_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    counselor_id TEXT,
                    start_time TEXT,
                    client_name TEXT,
                    client_email TEXT,
                    status TEXT
                );
                CREATE TABLE IF NOT EXISTS audit_logs (
                    log_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    booking_id TEXT,
                    event_type TEXT,
                    from_status TEXT,
                    to_status TEXT,
                    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
                );
                CREATE UNIQUE INDEX IF NOT EXISTS idx_slots_counselor_time ON slots(counselor_id, start_time);
            """)

    def register_counselor(self, counselor_id: str, name: str, specialty: str):
        if not counselor_id or not name:
            raise ValueError("counselor_id and name must be non-empty")
        try:
            with self.conn:
                self.conn.execute("INSERT INTO counselors VALUES (?, ?, ?)", (counselor_id, name, specialty))
        except sqlite3.IntegrityError:
            raise ValueError(f"Counselor {counselor_id} already exists")

    def add_slot(self, counselor_id: str, start_time: str):
        with self.conn:
            c = self.conn.execute("SELECT 1 FROM counselors WHERE counselor_id = ?", (counselor_id,)).fetchone()
            if not c:
                raise ValueError("Counselor does not exist")
            try:
                slot_id = str(uuid.uuid4())
                self.conn.execute("INSERT INTO slots VALUES (?, ?, ?, ?)", (slot_id, counselor_id, start_time, "AVAILABLE"))
                return {"slot_id": slot_id, "counselor_id": counselor_id, "start_time": start_time, "status": "AVAILABLE"}
            except sqlite3.IntegrityError:
                raise ValueError("Slot already exists")

    def block_slot(self, counselor_id: str, start_time: str):
        with self.conn:
            slot = self.conn.execute("SELECT status FROM slots WHERE counselor_id = ? AND start_time = ?", (counselor_id, start_time)).fetchone()
            if not slot or slot['status'] != "AVAILABLE":
                raise ValueError("Slot must exist and be AVAILABLE to be blocked")
            self.conn.execute("UPDATE slots SET status = 'BLOCKED' WHERE counselor_id = ? AND start_time = ?", (counselor_id, start_time))

    def query_available_slots(self, counselor_id: Optional[str] = None, date_prefix: Optional[str] = None):
        query = "SELECT * FROM slots WHERE status = 'AVAILABLE'"
        params = []
        if counselor_id:
            query += " AND counselor_id = ?"
            params.append(counselor_id)
        if date_prefix:
            query += " AND start_time LIKE ?"
            params.append(f"{date_prefix}%")
        query += " ORDER BY start_time ASC"

        cursor = self.conn.execute(query, params)
        return [dict(row) for row in cursor.fetchall()]

    def issue_session_pass(self, client_email: str, sessions_to_add: int, idempotency_key: str):
        if not client_email or sessions_to_add <= 0:
            raise ValueError("Invalid email or sessions to add")

        with self.conn:
            existing = self.conn.execute("SELECT * FROM pass_ledger WHERE idempotency_key = ?", (idempotency_key,)).fetchone()
            if existing:
                return self.get_session_pass(client_email)

            self.conn.execute("INSERT INTO pass_ledger (client_email, entry_type, delta_sessions, idempotency_key) VALUES (?, ?, ?, ?)",
                             (client_email, "ISSUE", sessions_to_add, idempotency_key))
            self.conn.execute("""
                INSERT INTO session_passes (client_email, remaining_sessions, used_sessions) 
                VALUES (?, ?, 0) 
                ON CONFLICT(client_email) DO UPDATE SET remaining_sessions = remaining_sessions + ?
            """, (client_email, sessions_to_add, sessions_to_add))

            return self.get_session_pass(client_email)

    def get_session_pass(self, client_email: str):
        row = self.conn.execute("SELECT * FROM session_passes WHERE client_email = ?", (client_email,)).fetchone()
        if not row:
            return {"client_email": client_email, "remaining_sessions": 0, "used_sessions": 0}
        return dict(row)

    def create_booking(self, counselor_id: str, start_time: str, client_name: str, client_email: str, idempotency_key: Optional[str] = None):
        if idempotency_key:
            existing = self.conn.execute("SELECT * FROM bookings WHERE idempotency_key = ?", (idempotency_key,)).fetchone()
            if existing:
                return dict(existing)

        with self.conn:
            slot = self.conn.execute("SELECT status FROM slots WHERE counselor_id = ? AND start_time = ?", (counselor_id, start_time)).fetchone()
            if not slot or slot['status'] != "AVAILABLE":
                raise ValueError("Slot is not available")

            pass_info = self.get_session_pass(client_email)
            if pass_info['remaining_sessions'] < 1:
                raise ValueError("Insufficient session passes")

            booking_id = str(uuid.uuid4())
            self.conn.execute("UPDATE slots SET status = 'BOOKED' WHERE counselor_id = ? AND start_time = ?", (counselor_id, start_time))
            self.conn.execute("UPDATE session_passes SET remaining_sessions = remaining_sessions - 1, used_sessions = used_sessions + 1 WHERE client_email = ?", (client_email,))
            self.conn.execute("INSERT INTO pass_ledger (client_email, booking_id, entry_type, delta_sessions, idempotency_key) VALUES (?, ?, ?, ?, ?)",
                             (client_email, booking_id, "USE", -1, f"use_{booking_id}"))
            self.conn.execute("INSERT INTO bookings VALUES (?, ?, ?, ?, ?, ?, ?)", (booking_id, counselor_id, start_time, client_name, client_email, "CONFIRMED", idempotency_key))
            self.conn.execute("INSERT INTO audit_logs (booking_id, event_type, from_status, to_status) VALUES (?, ?, ?, ?)", (booking_id, "BOOKING_CREATED", None, "CONFIRMED"))

            return self.lookup_booking(booking_id, client_email)

    def lookup_booking(self, booking_id: str, client_email: str):
        row = self.conn.execute("SELECT * FROM bookings WHERE booking_id = ?", (booking_id,)).fetchone()
        if not row or row['client_email'] != client_email:
            raise ValueError("Booking not found or email mismatch")
        return dict(row)

    def reschedule_booking(self, booking_id: str, client_email: str, new_counselor_id: str, new_start_time: str):
        with self.conn:
            booking = self.conn.execute("SELECT * FROM bookings WHERE booking_id = ? AND client_email = ? AND status = 'CONFIRMED'", (booking_id, client_email)).fetchone()
            if not booking:
                raise ValueError("Booking not found, email mismatch, or not confirmed")

            target_slot = self.conn.execute("SELECT status FROM slots WHERE counselor_id = ? AND start_time = ?", (new_counselor_id, new_start_time)).fetchone()
            if not target_slot or target_slot['status'] != "AVAILABLE":
                raise ValueError("Target slot is not available")

            old_counselor_id = booking['counselor_id']
            old_start_time = booking['start_time']

            self.conn.execute("UPDATE slots SET status = 'BOOKED' WHERE counselor_id = ? AND start_time = ?", (new_counselor_id, new_start_time))

            # Handle old slot: check waitlist
            waitlisted = self.conn.execute("SELECT * FROM waitlist WHERE counselor_id = ? AND start_time = ? AND status = 'WAITING' ORDER BY waitlist_id ASC", (old_counselor_id, old_start_time)).fetchone()

            if waitlisted:
                # Try to promote first eligible
                # We need to check all waitlisted in order
                all_waitlisted = self.conn.execute("SELECT * FROM waitlist WHERE counselor_id = ? AND start_time = ? AND status = 'WAITING' ORDER BY waitlist_id ASC", (old_counselor_id, old_start_time)).fetchall()
                promoted = False
                for w in all_waitlisted:
                    wp = self.get_session_pass(w['client_email'])
                    if wp['remaining_sessions'] >= 1:
                        # Promote
                        w_booking_id = str(uuid.uuid4())
                        self.conn.execute("UPDATE waitlist SET status = 'PROMOTED' WHERE waitlist_id = ?", (w['waitlist_id'],))
                        self.conn.execute("UPDATE session_passes SET remaining_sessions = remaining_sessions - 1, used_sessions = used_sessions + 1 WHERE client_email = ?", (w['client_email'],))
                        self.conn.execute("INSERT INTO pass_ledger (client_email, booking_id, entry_type, delta_sessions, idempotency_key) VALUES (?, ?, ?, ?, ?)",
                                         (w['client_email'], w_booking_id, "USE", -1, f"use_{w_booking_id}"))
                        self.conn.execute("INSERT INTO bookings VALUES (?, ?, ?, ?, ?, ?, ?)", (w_booking_id, old_counselor_id, old_start_time, w['client_name'], w['client_email'], "CONFIRMED", None))
                        self.conn.execute("INSERT INTO audit_logs (booking_id, event_type, from_status, to_status) VALUES (?, ?, ?, ?)", (w_booking_id, "WAITLIST_PROMOTED", None, "CONFIRMED"))
                        promoted = True
                        break
                if not promoted:
                    self.conn.execute("UPDATE slots SET status = 'AVAILABLE' WHERE counselor_id = ? AND start_time = ?", (old_counselor_id, old_start_time))
            else:
                self.conn.execute("UPDATE slots SET status = 'AVAILABLE' WHERE counselor_id = ? AND start_time = ?", (old_counselor_id, old_start_time))

            self.conn.execute("UPDATE bookings SET counselor_id = ?, start_time = ? WHERE booking_id = ?", (new_counselor_id, new_start_time, booking_id))
            self.conn.execute("INSERT INTO audit_logs (booking_id, event_type, from_status, to_status) VALUES (?, ?, ?, ?)", (booking_id, "BOOKING_RESCHEDULED", "CONFIRMED", "CONFIRMED"))

            return self.lookup_booking(booking_id, client_email)

    def join_waitlist(self, counselor_id: str, start_time: str, client_name: str, client_email: str):
        with self.conn:
            slot = self.conn.execute("SELECT status FROM slots WHERE counselor_id = ? AND start_time = ?", (counselor_id, start_time)).fetchone()
            if not slot or slot['status'] != "BOOKED":
                raise ValueError("Slot must be BOOKED to join waitlist")

            pass_info = self.get_session_pass(client_email)
            if pass_info['remaining_sessions'] < 1:
                raise ValueError("Insufficient session passes to join waitlist")

            self.conn.execute("INSERT INTO waitlist (counselor_id, start_time, client_name, client_email, status) VALUES (?, ?, ?, ?, ?)",
                             (counselor_id, start_time, client_name, client_email, "WAITING"))

    def cancel_booking(self, booking_id: str, client_email: str):
        with self.conn:
            booking = self.conn.execute("SELECT * FROM bookings WHERE booking_id = ? AND client_email = ? AND status = 'CONFIRMED'", (booking_id, client_email)).fetchone()
            if not booking:
                raise ValueError("Booking not found, email mismatch, or not confirmed")

            self.conn.execute("UPDATE bookings SET status = 'CANCELLED' WHERE booking_id = ?", (booking_id,))
            self.conn.execute("UPDATE session_passes SET remaining_sessions = remaining_sessions + 1, used_sessions = used_sessions - 1 WHERE client_email = ?", (client_email,))
            self.conn.execute("INSERT INTO pass_ledger (client_email, booking_id, entry_type, delta_sessions, idempotency_key) VALUES (?, ?, ?, ?, ?)",
                             (client_email, booking_id, "RESTORE", 1, f"restore_{booking_id}"))
            self.conn.execute("INSERT INTO audit_logs (booking_id, event_type, from_status, to_status) VALUES (?, ?, ?, ?)", (booking_id, "BOOKING_CANCELLED", "CONFIRMED", "CANCELLED"))

            counselor_id = booking['counselor_id']
            start_time = booking['start_time']

            # Waitlist Auto-Promotion
            all_waitlisted = self.conn.execute("SELECT * FROM waitlist WHERE counselor_id = ? AND start_time = ? AND status = 'WAITING' ORDER BY waitlist_id ASC", (counselor_id, start_time)).fetchall()
            promoted = False
