                                   (w['client_email'], booking_id, "USE", -1, str(uuid.uuid4())))
                self.conn.execute("INSERT INTO audit_logs (booking_id, event_type, from_status, to_status, timestamp) VALUES (?,?,?,?,?)", 
                                   (booking_id, "WAITLIST_PROMOTED", None, "CONFIRMED", datetime.datetime.now().isoformat()))
